local component=require("component");local event=require("event");local thread=require("thread");local computer=require("computer");local config=require("config.config");local M={};local box=component.isAvailable("chat_box")and component.chat_box or nil;local running=false;local function say(m)if box then pcall(box.say,m)end end
function M.notifyChanges(c)for _,v in ipairs(c or {})do say("§e"..v.player..(v.type=="joined"and"§a§l "or"§c§l ")..v.message)end end
function M.notifyMissing(c,f,e)if c>0 then say("§c§l⚠ Отсутствует реакторов: "..c..". Обнаружено "..f.." из "..e)end end
function M.start(p)if running or not box then return end;running=true;box.setName("§9§l"..config.chatTitle.."§7§o");thread.create(function()while running do local _,_,n,m=event.pull(1,"chat_message");if n and m and p.allowed(n)then if m=="@sleep"then computer.shutdown(true)elseif m=="@help"then say("@add, @remove, @greeting, @farewell, @sleep")elseif m:match("^@add ")then local _,x=p.add(m:match("^@add%s+(.+)$"));say(x)elseif m:match("^@remove ")then local _,x=p.remove(m:match("^@remove%s+(.+)$"));say(x)elseif m:match("^@greeting ")then local a,b=m:match("^@greeting%s+(%S+)%s+(.+)$");local _,x=p.setGreeting(a,b);say(x)elseif m:match("^@farewell ")then local a,b=m:match("^@farewell%s+(%S+)%s+(.+)$");local _,x=p.setFarewell(a,b);say(x)end end end end)end
return M
